export type Cell = [number, number]; // [x, y]

const NEIGHBORS_TO_SURVIVE = 2;
const NEIGHBORS_TO_BE_BORN = 3;

function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const isSameCell = otherX === x && otherY === y;
  return !isSameCell && Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
}

function countLiveNeighbors(cells: Cell[], cell: Cell): number {
  return cells.filter((other) => isNeighbor(cell, other)).length;
}

function isLive(cells: Cell[], [x, y]: Cell): boolean {
  return cells.some(([liveX, liveY]) => liveX === x && liveY === y);
}

function neighborsOf([x, y]: Cell): Cell[] {
  const offsets = [-1, 0, 1];
  return offsets
    .flatMap((dx) => offsets.map((dy): Cell => [x + dx, y + dy]))
    .filter((candidate) => isNeighbor([x, y], candidate));
}

export function nextGeneration(cells: Cell[]): Cell[] {
  const survivors = cells.filter(
    (cell) => countLiveNeighbors(cells, cell) === NEIGHBORS_TO_SURVIVE,
  );

  const births = cells
    .flatMap(neighborsOf)
    .filter(
      (candidate) =>
        !isLive(cells, candidate) &&
        countLiveNeighbors(cells, candidate) === NEIGHBORS_TO_BE_BORN,
    )
    .filter(
      (candidate, index, all) =>
        all.findIndex((other) => isNeighbor([NaN, NaN], other)) === -1 ||
        all.findIndex(
          ([x, y]) => x === candidate[0] && y === candidate[1],
        ) === index,
    );

  return [...survivors, ...births];
}

